export function joystickVector(dx,dy,radius=52,deadzone=.12){const length=Math.hypot(dx,dy),magnitude=Math.min(1,length/radius);if(magnitude<deadzone)return{x:0,y:0};return{x:dx/(length||1)*magnitude,y:dy/(length||1)*magnitude};}
export function canvasPoint(rect,clientX,clientY,width=1280,height=720){const scale=Math.min(rect.width/width,rect.height/height),left=rect.left+(rect.width-width*scale)/2,top=rect.top+(rect.height-height*scale)/2;return{x:Math.max(0,Math.min(width,(clientX-left)/scale)),y:Math.max(0,Math.min(height,(clientY-top)/scale))};}
export class TouchInput {
 constructor(game){this.cleanups=[];this.game=game;this.vector={x:0,y:0};this.attackHeld=false;this.joyPointer=null;this.attackPointer=null;this.mode='auto';this.joy=document.getElementById('joystick');this.thumb=document.getElementById('joystick-thumb');this.attack=document.getElementById('touch-attack');
  this.listen(this.joy,'pointerdown',e=>this.beginJoystick(e));this.listen(this.joy,'pointermove',e=>this.moveJoystick(e));for(const event of ['pointerup','pointercancel','lostpointercapture'])this.listen(this.joy,event,e=>this.endJoystick(e));
  this.listen(this.attack,'pointerdown',e=>{if(!this.canPlay()||this.attackPointer!==null)return;e.preventDefault();this.attackPointer=e.pointerId;this.attack.setPointerCapture(e.pointerId);this.attackHeld=true;this.game.attack();});for(const event of ['pointerup','pointercancel','lostpointercapture'])this.listen(this.attack,event,e=>{if(e.pointerId===this.attackPointer){this.attackHeld=false;this.attackPointer=null;}});
  document.querySelectorAll('[data-touch-action]').forEach(button=>this.listen(button,'pointerdown',e=>{if(!this.canPlay()||button.disabled)return;e.preventDefault();const action=button.dataset.touchAction;({dash:()=>game.dash(),heavy:()=>game.heavyAttack(),nova:()=>game.novaAttack(),interact:()=>game.interact(),potion:()=>game.heal(),weapon:()=>game.switchWeapon()})[action]?.();}));
  document.querySelectorAll('[data-touch-skill]').forEach(b=>this.listen(b,'pointerdown',e=>{e.preventDefault();if(this.canPlay())game.cast(Number(b.dataset.touchSkill));}));
  this.listen(window,'blur',()=>this.reset());this.listen(window,'resize',()=>this.refresh());this.refresh();
 }
 listen(target,type,handler){target.addEventListener(type,handler);this.cleanups.push(()=>target.removeEventListener?.(type,handler));} dispose(){this.reset();for(const off of this.cleanups.splice(0))off();} canPlay(){return this.game.state==='battle'&&!this.game.rpg?.transitioning&&!this.game.victoryDelay&&!document.getElementById('modal').open&&!this.game.display?.blocked;}
 refresh(){this.enabled=this.mode==='touch'||this.mode==='auto'&&(!!window.matchMedia?.('(pointer: coarse)').matches||(globalThis.navigator?.maxTouchPoints||0)>0);document.body.classList.toggle('touch-enabled',this.enabled);if(!this.enabled)this.reset();this.game.display?.sync();}
 setMode(mode){this.mode=['auto','touch','keyboard'].includes(mode)?mode:'auto';this.reset();this.refresh();}
 beginJoystick(e){if(!this.canPlay()||this.joyPointer!==null)return;e.preventDefault();this.joyPointer=e.pointerId;this.joy.setPointerCapture(e.pointerId);this.moveJoystick(e);}
 moveJoystick(e){if(e.pointerId!==this.joyPointer)return;e.preventDefault();const r=this.joy.getBoundingClientRect(),radius=r.width*.34;this.vector=joystickVector(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2,radius);this.thumb.style.transform=`translate(${this.vector.x*radius}px, ${this.vector.y*radius}px)`;}
 endJoystick(e){if(e.pointerId!==this.joyPointer)return;this.joyPointer=null;this.vector={x:0,y:0};this.thumb.style.transform='translate(0,0)';}
 reset(){const jp=this.joyPointer,ap=this.attackPointer;this.joyPointer=null;this.attackPointer=null;this.vector={x:0,y:0};this.attackHeld=false;this.thumb.style.transform='translate(0,0)';if(jp!==null&&this.joy.hasPointerCapture?.(jp))this.joy.releasePointerCapture(jp);if(ap!==null&&this.attack.hasPointerCapture?.(ap))this.attack.releasePointerCapture(ap);}
 updateHud(){const p=this.game.player;document.getElementById('touch-focus-value').textContent=`공명 ${Math.floor(p.focus)}`;document.getElementById('touch-focus-bar').style.width=p.focus+'%';for(const [id,cooldown]of [['touch-dash',p.dash],['touch-heavy',p.heavy],['touch-nova',p.nova]]){const b=document.getElementById(id);b.disabled=cooldown>0||id==='touch-nova'&&p.focus<50;b.dataset.cooldown=cooldown>0?Math.ceil(cooldown)+'':'';b.style.setProperty?.('--cooldown',String(cooldown/(id==='touch-dash'?1.8:id==='touch-heavy'?4:8)));}
  document.getElementById('touch-interact').disabled=!this.game.nearNode()&&!this.game.rpg?.nearPoint();document.getElementById('touch-potion-count').textContent=String(this.game.potions);document.getElementById('touch-weapon-name').textContent=['거울빛','자기꽃','월륜'][this.game.weaponIndex];document.querySelectorAll('[data-touch-skill]').forEach(b=>{const i=Number(b.dataset.touchSkill),cd=this.game.cooldowns[i];b.disabled=!this.game.save.cleared.includes(i)||cd>0;b.dataset.cooldown=cd>0?Math.ceil(cd)+'':'';});
 }
}
export function movementVector(keys,analog={x:0,y:0}){const x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0),length=Math.hypot(x,y);return length?{x:x/length,y:y/length}:analog;}

